#!/usr/bin/env node
// Generate TypeScript types + endpoint tables from specs/contracts/*/openapi.yaml.
// Source of truth lives in specs/contracts/. Do not edit generated files manually.

import {
  readFileSync,
  writeFileSync,
  mkdirSync,
  readdirSync,
  existsSync
} from "node:fs";
import { resolve, dirname } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import openapiTS, { astToString } from "openapi-typescript";
import { parse as parseYaml } from "yaml";

const __dirname = dirname(fileURLToPath(import.meta.url));
const WEB_DIR = resolve(__dirname, "..");
const ROOT_DIR = resolve(WEB_DIR, "../..");
const CONTRACTS_DIR = resolve(ROOT_DIR, "specs/contracts");
const OUTPUT_DIR = resolve(WEB_DIR, "src/shared/api/generated");

function discoverModules() {
  if (!existsSync(CONTRACTS_DIR)) return [];
  const moduleDirs = readdirSync(CONTRACTS_DIR, { withFileTypes: true })
    .filter(
      (e) =>
        e.isDirectory() &&
        existsSync(resolve(CONTRACTS_DIR, e.name, "openapi.yaml"))
    )
    .map((e) => ({
      name: e.name,
      yamlPath: resolve(CONTRACTS_DIR, e.name, "openapi.yaml")
    }));

  const sharedYaml = resolve(CONTRACTS_DIR, "shared.yaml");
  if (existsSync(sharedYaml)) {
    moduleDirs.push({ name: "shared", yamlPath: sharedYaml });
  }
  return moduleDirs.sort((a, b) => a.name.localeCompare(b.name));
}

function toRepoRelative(path) {
  return path.replace(ROOT_DIR + "/", "");
}

function generatedBanner(sourcePath) {
  return [
    "// <auto-generated/>",
    "// This file is generated. Do not edit manually.",
    `// Source of truth: ${toRepoRelative(sourcePath)}`,
    "// Regenerate via: scripts/quality/codegen-frontend.sh",
    ""
  ].join("\n");
}

function generateEndpoints(yamlPath, moduleName) {
  const doc = parseYaml(readFileSync(yamlPath, "utf8"));
  const paths = doc.paths;
  if (!paths || Object.keys(paths).length === 0) return null;

  const API_PREFIX = "/api/v1";
  const lines = [generatedBanner(yamlPath), "\n"];
  const entries = [];

  for (const [pathTemplate, methods] of Object.entries(paths)) {
    const clientPath = pathTemplate.startsWith(API_PREFIX)
      ? pathTemplate.slice(API_PREFIX.length)
      : pathTemplate;

    for (const [, operation] of Object.entries(methods)) {
      if (typeof operation !== "object" || !operation.operationId) continue;

      const paramMatches = [...clientPath.matchAll(/\{(\w+)\}/g)];
      const params = paramMatches.map((m) => m[1]);
      const paramSignature = params.map((p) => `${p}: string`).join(", ");

      let pathExpr;
      if (params.length > 0) {
        const tpl = clientPath.replace(
          /\{(\w+)\}/g,
          (_, name) => `\${${name}}`
        );
        pathExpr = "`" + tpl + "`";
      } else {
        pathExpr = `"${clientPath}"`;
      }

      entries.push({
        operationId: operation.operationId,
        params: paramSignature,
        pathExpr
      });
    }
  }

  if (entries.length === 0) return null;

  lines.push(`export const ${moduleName}Endpoints = {\n`);
  for (const entry of entries) {
    lines.push(
      `  ${entry.operationId}: (${entry.params}) => ${entry.pathExpr},\n`
    );
  }
  lines.push("} as const;\n");

  return lines.join("");
}

async function generateTypes(yamlPath) {
  const ast = await openapiTS(pathToFileURL(yamlPath));
  return `${generatedBanner(yamlPath)}\n${astToString(ast)}`;
}

async function main() {
  const modules = discoverModules();
  if (modules.length === 0) {
    console.log(`No contract modules found in ${CONTRACTS_DIR}`);
    return;
  }

  for (const mod of modules) {
    console.log(
      `  ${mod.name}: types${mod.name === "shared" ? "" : " + endpoints"}`
    );
    const outDir = resolve(OUTPUT_DIR, mod.name);
    mkdirSync(outDir, { recursive: true });

    const typesContent = await generateTypes(mod.yamlPath);
    writeFileSync(resolve(outDir, "types.ts"), typesContent);

    if (mod.name !== "shared") {
      const endpointsContent = generateEndpoints(mod.yamlPath, mod.name);
      if (endpointsContent) {
        writeFileSync(resolve(outDir, "endpoints.ts"), endpointsContent);
      }
    }
  }

  console.log("Frontend contract codegen complete.");
}

main().catch((err) => {
  console.error("Frontend contract codegen failed:", err);
  process.exit(1);
});
